import {COURSE} from './core.mjs';
import {proofIsCurrent} from './operations.mjs';
import {buildRunReport} from './run-report.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function connectionCards(cases,backend,cfg={}){
 const latest=(predicate)=>cases.filter(predicate).sort((a,b)=>Date.parse(b.sources?.payment?.checkedAt||b.createdAt)-Date.parse(a.sources?.payment?.checkedAt||a.createdAt))[0];
 const payment=latest(s=>s.capture?.source==='paypal-sandbox'&&s.sources?.payment),access=latest(s=>s.sources?.access&&(!cfg.courseAccess||s.intakeMode==='sandbox'));
 const cards=[
 ['PayPal sandbox',!backend?'Simulated':payment?.sources.payment.status==='unavailable'?'Check failed':payment?'Evidence checked':cfg.paypal?'Configured · not checked':'Not configured','Payment must match the exact purchase. A successful case read does not check every transaction.','Set PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET in the PayTrace server environment (Azure App Service settings or local .env). Complete sandbox checkout, then refresh that case.',payment?.sources.payment.lastSuccessAt],
 ['Course access',!backend?'Simulated':access?.sources.access.status==='unavailable'?'Check failed':access?.sources.access.system==='External course access service'?'Separate service checked':access?'Demo service checked':cfg.courseAccess?'Separate service configured':'Demo service ready',cfg.courseAccess?'Sandbox cases can use a separately hosted course-access service. The current case identifies which source was checked.':'Uses the built-in demo course service.','Open a sandbox case to inspect its entitlement. Verify protected lesson content after an approved correction.',access?.sources.access.lastSuccessAt],
 ['AI specialists',!backend||!cfg.ai?'Scripted demonstration':cases.some(s=>s.review&&s.review.mode!=='scripted')?'Model review recorded':'Configured · not checked','Evidence references support inspection; they are not a guarantee of accuracy.','Set OPENAI_API_KEY and OPENAI_MODEL on the server. Unlock the operator session and investigate a case.',null],
 ['Render Workflows',!backend||!cfg.workflows?'Not configured':cases.some(s=>s.job?.error)?'Run needs attention':cases.some(s=>s.job?.pending)?'Run in progress':cases.some(s=>s.job?.runId)?'Run recorded':'Configured · not checked','Investigation and approved recovery are separate runs. A recorded run is not a connection health check.','Deploy workflows, configure the task identifiers and shared secret, then inspect both runs in Render.',null]
 ];
 return `<div class="connection-banner"><strong>Setup → evidence → verified outcome</strong><p>Statuses reflect configuration and records in this workspace. Secrets stay in your server environment.</p></div><div class="connection-grid">${cards.map(([name,status,copy,setup,at],i)=>`<section class="surface connection-card"><span class="eyebrow">0${i+1} / CONNECTION</span><h2>${name}</h2><span class="badge neutral">${esc(status)}</span><p>${copy}</p>${at?`<small>Last successful source read: ${esc(new Date(at).toLocaleString())}</small>`:''}<details><summary>Setup and next check</summary><p>${setup}</p></details></section>`).join('')}</div><section class="setup-note"><h2>Complete one purchase from start to finish.</h2><p>Start with a sandbox case, confirm payment, review the evidence, approve the correction, then verify the lesson.</p><a class="button" href="focus.html">Return to recovery desk and create a sandbox case</a> <a class="button" href="https://github.com/sagitta414/paytrace-recover/blob/main/docs/BUILD-README.md" target="_blank" rel="noopener">Deployment guide ↗</a></section>`;
}
export function caseExperience(s,{uncertain=false,backend=false}={}){
 const verified=proofIsCurrent(s)&&!uncertain,stages=[['Payment',s.capture?.status==='COMPLETED'],['Access checked',s.sources?.access?.status==='available'],['Review',!!s.review],['Approval',!!s.approval],['Verification',verified]],report=buildRunReport(s,{backend});
 return `${uncertain?'<section class="approval-brief" role="status"><h3>Let’s confirm what happened.</h3><p>A failed request does not prove an access change failed. Refresh the records before deciding what to do next.</p><button class="button" data-action="refresh">Check current status</button></section>':''}<section class="case-progress" aria-label="Recovery checkpoints"><div class="section-head"><h3>From payment to access</h3><span class="subtle">${s.job?.pending?'Workflow running':uncertain?'Refresh required':'Current case'}</span></div><ol>${stages.map(([label,done])=>`<li class="${done&&!uncertain?'checked':''}"><span>${done&&!uncertain?'✓':'○'}</span>${label}</li>`).join('')}</ol>${s.paymentSignal?.source==='paypal-sandbox-webhook'?`<p class="footnote">PayPal capture event verified · payment rechecked ${esc(new Date(s.paymentSignal.confirmedAt).toLocaleString())} · ${esc(s.paymentSignal.eventId)}</p>`:''}${s.job?.runId?`<p class="footnote">Workflow reference: ${esc(s.job.runId)}</p>`:''}${s.job?.error?`<p role="status">Workflow needs attention. Refresh status before another action.</p>`:''}</section>
 ${s.rehearsal?`<section class="approval-brief"><span class="eyebrow">${s.writes?'APPROVED CHANGE':'YOUR DECISION'}</span><h3>One course. One customer. One access grant.</h3><dl><div><dt>Customer</dt><dd>${esc(s.customerName)}</dd></div><div><dt>Purchased course</dt><dd>${esc(COURSE.name)}</dd></div><div><dt>Correction</dt><dd>Activate this purchase’s course entitlement</dd></div><div><dt>Payment</dt><dd>Existing capture · no additional charge or refund</dd></div></dl><p>${s.approval?'Approval recorded for this evidence version.':'Approval applies to the previewed evidence. Changes require a new review.'}</p></section>`:''}
 <section class="learner-preview"><div><span class="eyebrow">CUSTOMER VIEW / ${s.sources?.access?.system==='External course access service'?'SEPARATE COURSE SERVICE':'DEMO COURSE'}</span><h3>${verified?'The lesson is ready.':s.entitlement.active?'Access updated. Proof still matters.':'What the customer is waiting for.'}</h3><p>${esc(COURSE.name)}</p></div><div class="lesson-tile"><span>${s.entitlement.active?'ACCESS RECORD ACTIVE':'COURSE LOCKED'}</span><strong>01 / See the light</strong><p>${verified?'The independent check retrieved this lesson for the purchased entitlement.':uncertain?'Current access is unconfirmed. Refresh the case before continuing.':'The customer’s lesson becomes available only when the correct entitlement is active.'}</p><button class="button" data-lesson-preview ${!s.entitlement.active||uncertain?'disabled':''}>${backend?'Check & open lesson':'Preview simulated lesson'}</button><div class="lesson-result" role="status"></div></div></section>
 ${s.proof?`<section class="verification-receipt ${verified?'passed':''}"><span class="eyebrow">${verified?'VERIFIED OUTCOME':'VERIFICATION INCOMPLETE'}</span><h3>${verified?'A receipt for the outcome.':'Keep this case open.'}</h3><p>${esc(s.customerName)} · ${esc(COURSE.name)}</p><ul>${s.proof.checks.map(c=>`<li>${c.ok?'✓':'!'} ${esc(c.label)}</li>`).join('')}</ul><p>Checked ${esc(new Date(s.proof.at).toLocaleString())}</p><p class="footnote">${esc(s.proof.transport)} · ${s.writes} access grant(s) · ${s.reads} verification attempt(s). ${uncertain?'This result is not currently confirmed.':''}</p><button class="button" data-action="receipt">Download case receipt</button></section>`:''}${runReportPanel(report,uncertain)}`;
}
export function runReportPanel(report,uncertain=false){
 const status=report.connectedSandboxProof&&!uncertain?'Connected sandbox proof':uncertain?'Refresh required':report.headline;
 return `<section class="run-report"><div class="run-report-head"><div><span class="eyebrow">RUN REPORT / SAVED EVIDENCE</span><h3>${esc(status)}</h3><p>See exactly which parts used connected services, and which still rely on the demo.</p></div><div class="run-report-count"><strong>${report.passed}<small> / ${report.total}</small></strong><span>connected checks</span></div></div>${runReportTimeline(report)}<details class="run-report-details"><summary>Inspect all six source checks</summary><div class="run-report-grid">${report.checks.map(c=>`<div class="run-report-item ${esc(c.status)}"><span class="run-report-mark">${c.status==='passed'?'✓':c.status==='failed'?'!':'·'}</span><div><strong>${esc(c.label)}</strong><span>${esc(c.status==='passed'?'Connected':c.status==='demo'?'Demo evidence':c.status==='failed'?'Needs attention':c.status==='not-needed'?'No change needed':'Not yet shown')}</span><small>${esc(c.detail)}</small>${c.reference?`<code>${esc(c.reference)}</code>`:''}${c.sourceIds?.length?`<small>Sources: ${esc(c.sourceIds.join(', '))}</small>`:''}</div></div>`).join('')}</div></details><p class="run-report-note">${esc(report.note)}</p><button class="button" data-action="run-report">Download run report</button></section>`;
}
export function runReportTimeline(report){
 const ids=['payment','agents','approval','workflow','verification'];
 const checks=ids.map(id=>report.checks.find(item=>item.id===id)).filter(Boolean);
 return `<div class="receipt-timeline" aria-label="Recovery evidence timeline"><div class="receipt-timeline-head"><span class="eyebrow">RECOVERY RECEIPT</span><strong>From payment to proof</strong><small>Saved evidence · ${esc(report.scope)}</small></div><ol>${checks.map((item,index)=>`<li class="${esc(item.status)}"><span class="receipt-timeline-index">${String(index+1).padStart(2,'0')}</span><div><strong>${esc(item.label)}</strong><p>${esc(item.detail)}</p><small>${item.checkedAt?esc(new Date(item.checkedAt).toLocaleString()):'Time not recorded'} · ${esc(item.status==='passed'?'Connected':item.status==='demo'?'Demo evidence':item.status==='failed'?'Needs attention':item.status==='not-needed'?'No change needed':'Awaiting evidence')}</small></div></li>`).join('')}</ol><p>Customer confirmation is tracked separately from technical verification.</p></div>`;
}
export function mountExperience(root,s,{backend,uncertain,api}){
 if(!s)return;const body=root.querySelector('.sheet-body');if(!body)return;
 const panel=document.createElement('div');panel.className='case-experience';panel.innerHTML=caseExperience(s,{backend,uncertain});body.append(panel);
 const button=panel.querySelector('[data-lesson-preview]'),result=panel.querySelector('.lesson-result');
 button.onclick=async()=>{button.disabled=true;result.textContent='Checking the selected learner’s access…';try{if(backend){const lesson=await api('lesson?caseId='+encodeURIComponent(s.id));if(!lesson.accessible||lesson.userId!==s.order.userId||lesson.courseId!==s.order.courseId)throw Error('The selected case changed. Reopen this case before viewing the lesson.');result.textContent=lesson.title+' '+lesson.body;}else result.textContent='Simulated lesson preview: Find soft window light and make three frames. This did not retrieve protected content from a server.';}catch(e){result.textContent='Lesson could not be confirmed. '+e.message;}finally{button.disabled=false;}};
}
